import * as pc from 'playcanvas';
import type { Assets } from '../core/assets';

/**
 * Rigged humanoid with procedural animation.
 * The CC0 Kenney rigs ship without clips, so walk/run/idle/cuffed poses are
 * generated by rotating bones. Bone deltas are authored in model space and
 * converted into each bone's local frame using its bind pose.
 */

type BoneName =
  | 'Hips' | 'Spine' | 'Chest' | 'Neck' | 'Head'
  | 'LeftArm' | 'LeftForeArm' | 'RightArm' | 'RightForeArm'
  | 'LeftUpLeg' | 'LeftLeg' | 'RightUpLeg' | 'RightLeg' | 'LeftFoot' | 'RightFoot';

interface Bone {
  e: pc.Entity;
  bindLocal: pc.Quat;
  parentBind: pc.Quat;
  parentBindInv: pc.Quat;
  bindPos: pc.Vec3;
  side: number; // +1 / -1 for limbs (sign of model-space X), 0 for spine
}

export type Pose = 'normal' | 'cuffed' | 'talk' | 'handsUp' | 'kneel';

const tmpQ = new pc.Quat();
const tmpQ2 = new pc.Quat();
const axisX = new pc.Vec3(1, 0, 0);
const axisY = new pc.Vec3(0, 1, 0);
const axisZ = new pc.Vec3(0, 0, 1);
const DEG = Math.PI / 180;

export class Character {
  readonly entity: pc.Entity;
  readonly model: pc.Entity;
  private bones = new Map<BoneName, Bone>();
  private phase = Math.random() * 10;
  private idleT = Math.random() * 10;
  /** Current horizontal speed (m/s), set by the controller each frame. */
  speed = 0;
  pose: Pose = 'normal';
  private poseBlend = 0;
  /** Facing yaw in degrees (0 = +Z). */
  yaw = 0;
  readonly height = 1.78;
  ok = false;

  constructor(assets: Assets, modelKey: string, name: string) {
    this.entity = new pc.Entity(name);
    this.model = assets.instance(modelKey);
    this.entity.addChild(this.model);
    this.ok = !this.model.name.startsWith('missing:');
    if (!this.ok) return;

    // Kenney rig is ~2.41 units tall with a large head; normalise proportions.
    const scale = 0.775;
    this.model.setLocalScale(scale, scale, scale);

    // Capture bind pose (model root at identity → world == model space × scale).
    const names: BoneName[] = ['Hips', 'Spine', 'Chest', 'Neck', 'Head', 'LeftArm', 'LeftForeArm', 'RightArm', 'RightForeArm',
      'LeftUpLeg', 'LeftLeg', 'RightUpLeg', 'RightLeg', 'LeftFoot', 'RightFoot'];
    for (const n of names) {
      const e = this.model.findByName(n) as pc.Entity | null;
      if (!e) continue;
      const parent = e.parent as pc.Entity;
      const pb = parent.getRotation().clone();
      const wp = e.getPosition();
      this.bones.set(n, {
        e, bindLocal: e.getLocalRotation().clone(), parentBind: pb, parentBindInv: pb.clone().invert(),
        bindPos: e.getLocalPosition().clone(), side: 0,
      });
      void wp;
    }
    // Determine limb sides from hand positions so signs are rig-independent.
    for (const [side, prefix] of [[0, 'Left'], [0, 'Right']] as const) {
      void side;
      const hand = this.model.findByName(`${prefix}Hand`) as pc.Entity | null;
      const s = hand ? Math.sign(hand.getPosition().x) || 1 : prefix === 'Left' ? 1 : -1;
      for (const b of ['Arm', 'ForeArm', 'UpLeg', 'Leg', 'Foot']) {
        const bone = this.bones.get(`${prefix}${b}` as BoneName);
        if (bone) bone.side = s;
      }
    }
    // Smaller head = more grounded, less cartoony proportions.
    const head = this.bones.get('Head');
    if (head) head.e.setLocalScale(0.8, 0.8, 0.8);
  }

  /** Apply a model-space rotation (sequence of axis/angle) to a bone, relative to its bind pose. */
  private rot(name: BoneName, rotations: [pc.Vec3, number][]) {
    const b = this.bones.get(name);
    if (!b) return;
    // R = product of rotations (applied in order)
    const R = tmpQ.set(0, 0, 0, 1);
    for (const [axis, deg] of rotations) {
      if (!deg) continue;
      tmpQ2.setFromAxisAngle(axis, deg);
      R.mul2(tmpQ2, R);
    }
    // local = parentBind^-1 * R * parentBind * bindLocal
    const q = new pc.Quat().mul2(b.parentBindInv, R).mul(b.parentBind).mul(b.bindLocal);
    b.e.setLocalRotation(q);
  }

  update(dt: number) {
    this.entity.setLocalEulerAngles(0, this.yaw, 0);
    if (!this.ok) return;
    const sp = this.speed;
    const moving = Math.min(1, sp / 1.4);
    const running = Math.max(0, Math.min(1, (sp - 2.2) / 2.5));
    const cadence = 1.7 + sp * 0.62; // steps per second-ish
    this.phase += dt * cadence * Math.PI * (sp > 0.05 ? 1 : 0);
    this.idleT += dt;

    const target = this.pose === 'normal' ? 0 : 1;
    this.poseBlend += (target - this.poseBlend) * Math.min(1, dt * 6);

    const s = Math.sin(this.phase);
    const c = Math.cos(this.phase);
    const legAmp = (24 + 20 * running) * moving;
    const kneeAmp = (30 + 35 * running) * moving;
    const armAmp = (22 + 30 * running) * moving;
    const breathe = Math.sin(this.idleT * 1.6) * (1 - moving);

    // Legs (forward swing = negative X rotation)
    for (const [prefix, ph] of [['Left', 1], ['Right', -1]] as const) {
      const sw = s * ph;
      const kneelBlend = this.pose === 'kneel' ? this.poseBlend : 0;
      this.rot(`${prefix}UpLeg` as BoneName, [[axisX, -sw * legAmp - kneelBlend * (prefix === 'Left' ? 80 : 5)]]);
      const knee = Math.max(0, -(c * ph)) * kneeAmp + moving * 6 + kneelBlend * (prefix === 'Left' ? 85 : 95);
      this.rot(`${prefix}Leg` as BoneName, [[axisX, knee]]);
      this.rot(`${prefix}Foot` as BoneName, [[axisX, -knee * 0.25]]);
    }

    // Arms: T-pose → down, then swing / pose
    for (const [prefix, ph] of [['Left', -1], ['Right', 1]] as const) {
      const arm = this.bones.get(`${prefix}Arm` as BoneName);
      const side = arm?.side ?? (prefix === 'Left' ? 1 : -1);
      const swing = s * ph * armAmp;
      let lower = 74, fwd = -swing, elbow = 12 + moving * 18 + running * 35, twist = 0;
      const p = this.poseBlend;
      if (this.pose === 'cuffed') {
        lower = 74 - 10 * p; fwd = -swing * (1 - p) + 32 * p; elbow = elbow * (1 - p) + 70 * p; twist = 30 * p;
      } else if (this.pose === 'handsUp') {
        lower = 74 - 150 * p; fwd = -swing * (1 - p) - 10 * p; elbow = elbow * (1 - p) + 25 * p;
      } else if (this.pose === 'talk') {
        const g = Math.sin(this.idleT * (prefix === 'Left' ? 2.1 : 2.6)) * 0.5 + 0.5;
        fwd = -swing * (1 - p) - (18 + g * 22) * p * (prefix === 'Right' ? 1 : 0.4);
        elbow = elbow * (1 - p) + (35 + g * 30) * p * (prefix === 'Right' ? 1 : 0.5);
      }
      // lower: rotate about forward (Z) axis toward -Y; fwd: rotate about X (negative = forward)
      this.rot(`${prefix}Arm` as BoneName, [[axisZ, -side * lower], [axisX, fwd + breathe], [axisY, side * twist]]);
      // elbow bend toward +Z in bind frame = rotation about Y
      this.rot(`${prefix}ForeArm` as BoneName, [[axisY, -side * elbow]]);
    }

    // Torso
    const bob = Math.abs(c) * 0.035 * moving + breathe * 0.004;
    const hips = this.bones.get('Hips');
    if (hips) {
      const kneelDrop = this.pose === 'kneel' ? this.poseBlend * 0.42 : 0;
      this.model.setLocalPosition(0, -bob - kneelDrop, 0);
      this.rot('Hips', [[axisY, s * 6 * moving], [axisZ, c * 2.5 * moving]]);
    }
    this.rot('Spine', [[axisX, 4 * running + (this.pose === 'cuffed' ? 6 * this.poseBlend : 0)], [axisY, -s * 8 * moving]]);
    this.rot('Chest', [[axisX, breathe * 1.2]]);
    this.rot('Neck', [[axisY, Math.sin(this.idleT * 0.37) * 8 * (1 - moving)], [axisX, this.pose === 'cuffed' ? 12 * this.poseBlend : 0]]);
  }

  setPosition(x: number, y: number, z: number) { this.entity.setPosition(x, y, z); }
  get position() { return this.entity.getPosition(); }

  set visible(v: boolean) { this.entity.enabled = v; }
  get visible() { return this.entity.enabled; }
}

export function yawTowards(fromX: number, fromZ: number, toX: number, toZ: number) {
  return Math.atan2(toX - fromX, toZ - fromZ) / DEG;
}

export function lerpAngle(a: number, b: number, t: number) {
  let d = ((b - a + 540) % 360) - 180;
  return a + d * t;
}
